package com.healthwise.security;
import com.healthwise.user.repository.UserRepository; import io.jsonwebtoken.Claims; import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
/** Populates Spring Security's context from a Bearer JWT. */
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtAuthenticationFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims cl=jwt.parse(h.substring(7));users.findById(cl.getSubject()).filter(u->u.isEnabled()).ifPresent(u->{var a=u.getRoles().stream().map(role->new SimpleGrantedAuthority("ROLE_"+role.name())).toList();var auth=new UsernamePasswordAuthenticationToken(new CurrentUser(u.getId(),u.getEmail()),null,a);auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(r));SecurityContextHolder.getContext().setAuthentication(auth);});}catch(Exception ignored){SecurityContextHolder.clearContext();}c.doFilter(r,s);} }
